const KEY='triplan_full_year_v1', START=new Date('2026-10-12T12:00:00'), $=s=>document.querySelector(s);
function load(){try{return JSON.parse(localStorage.getItem(KEY))||{sessions:PLAN}}catch{return {sessions:PLAN}}}
let data=load(), currentMonday=(function(){
  const now=new Date();
  const planStart=new Date('2026-10-12T12:00:00');
  const planEnd=new Date('2027-09-30T12:00:00');
  if(now < planStart) return mondayOf(planStart);
  if(now > planEnd) return mondayOf(planEnd);
  return mondayOf(now);
})(), feedbackId=null;
function saveData(){localStorage.setItem(KEY,JSON.stringify(data))}
function iso(d){return d.toISOString().slice(0,10)} function addDays(d,n){const x=new Date(d);x.setDate(x.getDate()+n);return x}
function mondayOf(d){const x=new Date(d),k=(x.getDay()+6)%7;x.setDate(x.getDate()-k);x.setHours(12,0,0,0);return x}
function fmt(d){return d.toLocaleDateString('fr-FR',{day:'2-digit',month:'short'})}
function weekSessions(m){const a=iso(m),b=iso(addDays(m,6));return data.sessions.filter(s=>s.date>=a&&s.date<=b)}
function renderWeek(){const ws=weekSessions(currentMonday),deload=ws.some(s=>s.deload),phase=ws[0]?.phase||'';$('#weekTitle').textContent=`${fmt(currentMonday)} – ${fmt(addDays(currentMonday,6))}`;$('#weekBadge').innerHTML=`<span class="badge ${deload?'deload':''}">${deload?'DELOAD · ':''}${phase}</span>`;$('#weekGrid').innerHTML='';
for(let i=0;i<7;i++){const d=addDays(currentMonday,i),ds=iso(d),box=document.createElement('div');box.className='day';box.innerHTML=`<div class="dayhead"><b>${d.toLocaleDateString('fr-FR',{weekday:'short'}).replace('.','')}</b><span class="date">${fmt(d)}</span></div>`;const arr=data.sessions.filter(s=>s.date===ds);
if(arr.length && arr.every(s=>s.completed)){
  box.classList.add('day-complete');
  const hasHard = arr.some(s=>s.rating==='hard');
  if(hasHard) box.classList.add('day-hard');
  else box.classList.add('day-good');
}
if(!arr.length)box.innerHTML+='<div class="meta" style="margin-top:14px">Repos</div>';arr.forEach(s=>{const c=document.createElement('div');c.className='session';c.innerHTML=`<div class="sport">${s.sport}</div><h3>${s.title}</h3><div class="meta">${s.duration} min${s.adjusted?' · +5%':''}<br>${s.notes}</div>`;if(!s.completed){const b=document.createElement('button');b.textContent='Terminer + noter';b.style.marginTop='8px';b.onclick=()=>openFeedback(s.id);c.appendChild(b)}else{const map={easy:'Facile',normal:'Normal',hard:'Difficile'};const st=document.createElement('div');st.className='status';st.textContent=`✓ ${map[s.rating]}${s.comment?' · '+s.comment:''}`;c.appendChild(st)}box.appendChild(c)});$('#weekGrid').appendChild(box)}}
function openFeedback(id){feedbackId=id;const s=data.sessions.find(x=>x.id===id);$('#mTitle').textContent=s.title;$('#mRate').value='easy';$('#mComment').value='';$('#modal').classList.add('show')}
function adjustNext(s){const next=data.sessions.filter(x=>x.sport===s.sport&&x.date>s.date&&!x.completed).sort((a,b)=>a.date.localeCompare(b.date))[0];if(!next||next.deload||next.adjusted)return;next.duration=Math.max(1,Math.round(next.duration*1.05));next.adjusted=true}
$('#save').onclick=()=>{const s=data.sessions.find(x=>x.id===feedbackId);s.completed=true;s.rating=$('#mRate').value;s.comment=$('#mComment').value.trim();if(s.rating==='easy'&&!s.deload)adjustNext(s);saveData();$('#modal').classList.remove('show');renderWeek()};$('#cancel').onclick=()=>$('#modal').classList.remove('show');$('#prev').onclick=()=>{currentMonday=addDays(currentMonday,-7);renderWeek()};$('#next').onclick=()=>{currentMonday=addDays(currentMonday,7);renderWeek()};
document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.querySelectorAll('.view').forEach(v=>v.classList.remove('active'));$('#'+b.dataset.view).classList.add('active');if(b.dataset.view==='progress')renderProgress();if(b.dataset.view==='plan')renderPlan()});
function renderProgress(){const done=data.sessions.filter(s=>s.completed),mins=done.reduce((a,s)=>a+s.duration,0),easy=done.filter(s=>s.rating==='easy').length;$('#sDone').textContent=done.length;$('#sMin').textContent=mins;$('#sEasy').textContent=(done.length?Math.round(easy/done.length*100):0)+'%';$('#sWeeks').textContent=new Set(done.map(s=>iso(mondayOf(new Date(s.date+'T12:00:00'))))).size;drawChart()}
function drawChart(){const c=$('#chart'),ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);const g={};data.sessions.filter(s=>s.completed).forEach(s=>{const k=iso(mondayOf(new Date(s.date+'T12:00:00')));g[k]=(g[k]||0)+s.duration});const keys=Object.keys(g).sort().slice(-10),vals=keys.map(k=>g[k]),max=Math.max(60,...vals),pad=50,w=(c.width-pad*2)/Math.max(keys.length,1);keys.forEach((k,i)=>{const h=vals[i]/max*(c.height-90),x=pad+i*w+10,y=c.height-45-h;ctx.fillStyle='#6ea8fe';ctx.fillRect(x,y,Math.max(18,w-20),h);ctx.fillStyle='#f5f7fb';ctx.font='17px sans-serif';ctx.fillText(vals[i],x,y-7);ctx.fillStyle='#aab4c7';ctx.font='14px sans-serif';ctx.fillText(new Date(k+'T12:00:00').toLocaleDateString('fr-FR',{day:'2-digit',month:'2-digit'}),x,c.height-18)})}
[...new Set(PLAN.map(s=>s.phase))].forEach(p=>$('#phaseFilter').insertAdjacentHTML('beforeend',`<option>${p}</option>`));
function renderPlan(){const pf=$('#phaseFilter').value,sf=$('#sportFilter').value,arr=data.sessions.filter(s=>(!pf||s.phase===pf)&&(!sf||s.sport===sf)),by={};arr.forEach(s=>{const k=iso(mondayOf(new Date(s.date+'T12:00:00')));(by[k]??=[]).push(s)});$('#planList').innerHTML=Object.keys(by).sort().map(k=>{const a=by[k];return `<div class="plan-week"><h3>Semaine du ${new Date(k+'T12:00:00').toLocaleDateString('fr-FR',{day:'2-digit',month:'long',year:'numeric'})} ${a.some(x=>x.deload)?'<span class="badge deload">DELOAD</span>':''}</h3>${a.map(s=>`<div class="plan-row"><div><strong>${new Date(s.date+'T12:00:00').toLocaleDateString('fr-FR',{weekday:'short'})} · ${s.sport}</strong> — ${s.title}<br>${s.notes}</div><div>${s.duration} min</div></div>`).join('')}</div>`}).join('')}
$('#phaseFilter').onchange=renderPlan;$('#sportFilter').onchange=renderPlan;renderWeek();
